sys_script_include.script:
var ServiceNow_School_Utils = Class.create();
ServiceNow_School_Utils.prototype = {
    initialize: function() {},
    refQualRecordProducer: function() {
        let grCourses = new GlideRecord("x_1974925_servic_0_schedule"), coursesToShow = [];
        grCourses.addEncodedQuery("trainning_date>javascript:gs.endOfToday()^current_studentsLT_FIELDmax_students");
        grCourses.query();

        while (grCourses.next()) {
            if (!(grCourses.instructor == gs.getUserID())) {

                let grEnrollments = new GlideRecord("x_1974925_servic_0_enrollment");
                grEnrollments.addQuery("student", gs.getUserID());
                grEnrollments.addQuery("course.class_subject", grCourses.class_subject);
                grEnrollments.query();

                gs.info(grEnrollments.getRowCount());
                if (grEnrollments.getRowCount() == 0) {
                    coursesToShow.push(grCourses.getUniqueValue());
                } else if (grEnrollments.getRowCount() < 3) {
                    let auxSearch = false;
                    while (grEnrollments.next()) {
                        if (grEnrollments.course == grCourses.getUniqueValue()) {
                            auxSearch = true;
							break;
                        }
                    }
                    if (!auxSearch) {
                        coursesToShow.push(grCourses.getUniqueValue());
                    }
                }
            }
        }
        return "sys_idIN" + coursesToShow.join(",");
    },

    type: 'ServiceNow_School_Utils'
};
